// STUB — Phase 2
// Filtra leads elegíveis e prepara payloads para bia_core_v1

const leads = $input.item.json ?? [];
const leadArray = Array.isArray(leads) ? leads : (leads.data ?? leads.leads ?? []);

if (leadArray.length === 0) {
  console.log('[followup_v1] Nenhum lead elegível para follow-up');
  return [];
}

// Monta payload para cada lead no formato esperado pela bia_core_v1
const LIMITE_FOLLOWUPS = 3;

const payloads = leadArray
  .filter(lead => (lead.followupCount ?? 0) < LIMITE_FOLLOWUPS)
  .map(lead => ({
    json: {
      leadId: lead.id,
      leadNome: lead.nome ?? null,
      canal: lead.canalMensagem ?? 'whatsapp',
      mensagemCliente: 'followup_automatico',
      resumo: lead.resumo ?? null,
      contexto: [],
      _followup: true,
      _followupCount: (lead.followupCount ?? 0) + 1
    }
  }));

console.log(`[followup_v1] Disparando follow-up para ${payloads.length} leads`);
return payloads;
